function resolveBricks(state) {
  const { ball, bricks } = state;
  // For each brick, process. Since neighbours overlap, iterate over all bricks.
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      // resolve
      brickBounce(ball, brick);
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
