export function step(state, dt) {
  const { ball } = state;

  // Sub-step to avoid tunnelling through thin bricks at high speed.
  // Cap each sub-step so the ball moves at most ~10 px.
  const maxMove = 10;
  const totalMove = Math.hypot(ball.vx, ball.vy) * dt;
  const steps = Math.max(1, Math.ceil(totalMove / maxMove));
  const dtStep = dt / steps;

  let lost = false;
  for (let i = 0; i < steps; i++) {
    // move
    ball.x += ball.vx * dtStep;
    ball.y += ball.vy * dtStep;

    bounceWallsAndPaddle(state);
    lost = resolveBricks(state);
    if (lost) break;
  }
  return lost;
}
```

