export function step(state, dt) {
  const { ball, paddle } = state;

  // Sub-step the move so the ball can't tunnel through a brick at high speed.
  const stepSize = 10; // px, << brick width/height
  const speed = Math.hypot(ball.vx, ball.vy);
  const subSteps = Math.max(1, Math.ceil((speed * dt) / stepSize));
  const dt2 = dt / subSteps;

  let lost = false;
  for (let i = 0; i < subSteps && !lost; i++) {
    ball.x += ball.vx * dt2;
    ball.y += ball.vy * dt2;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks: resolve (bounce, push out), score, combo.
    resolveBricks(state);

    // Exit through the bottom
    if (ball.y - ball.r > HEIGHT) {
      lost = true;
    }
  }
  return lost;
}
```

