export function brickBounce(ball, brick) {
  // penetration depths on each side
  const penLeft = ball.x + ball.r - brick.x;      // ball entered from left side
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);

  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    // Side hit: flip vx, push out along x
    ball.vx = -ball.vx;
    if (penLeft < penRight) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
  } else if (penY < penX) {
    // Top/bottom hit: flip vy, push out along y
