//   * top/bottom hit  -> flip `vy`, push the ball out vertically;
//   * left/right hit  -> flip `vx`, push the ball out horizontally;
//   * corner (equal)  -> flip both components.
export function brickBounce(ball, brick) {
  // How far the ball's circle has sunk past each of the brick's four faces.
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);

  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    // Side hit: reverse horizontal travel and push out along x.
    ball.vx = -ball.vx;
    if (penLeft < penRight) ball.x = brick.x - ball.r; // hit from the left
    else ball.x = brick.x + brick.w + ball.r;          // hit from the right
  } else if (penY < penX) {
    // Top/bottom hit: reverse vertical travel and push out along y.
    ball.vy = -ball.vy;
    if (penTop < penBottom) ball.y = brick.y - ball.r; // hit from above
    else ball.y = brick.y + brick.h + ball.r;          // hit from below
  } else {
    // Corner: equal penetration on both axes -> flip both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    // Push the ball out along the dominant axis of travel.
    const horizontal = Math.abs(ball.vx) >= Math.abs(ball.vy);
    if (horizontal) {
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    } else {
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }
  }
}

// Resolves the ball against every live brick. Each brick is processed at most
// once per pass (the bounce applies exactly once, so adjacent seamless hits
// don't cancel each other out), and the ball is pushed back out so it can't
// re-trigger a sticky bounce on the next frame.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    brickBounce(ball, brick);
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks.
//
// The move is split into sub-steps of at most `BRICK_MAX_SUBSTEP` pixels so the
// ball can't tunnel through a thin brick between two discrete frames (its
// largest jump stays smaller than a brick), fixing #1's tunnelling case.
// Returns `true` if the ball is lost (exits through the bottom).
export const BRICK_MAX_SUBSTEP = 10;

export function step(state, dt) {
  const { ball, paddle } = state;

  const speed = Math.hypot(ball.vx, ball.vy);
  const subSteps = Math.max(1, Math.ceil((speed * dt) / BRICK_MAX_SUBSTEP));
  const dtStep = dt / subSteps;

  let lost = false;
  for (let i = 0; i < subSteps && !lost; i++) {
    ball.x += ball.vx * dtStep;
    ball.y += ball.vy * dtStep;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: bounce + push out + score + combo.
    resolveBricks(state);

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      lost = true;
    }
  }
  return lost;
}

